mapper.select:
SELECT f.*, g.group_name as group_name
FROM xxl_kettle_file f LEFT JOIN xxl_kettle_group g ON f.group_id = g.id
WHERE f.group_id = #{groupId}
AND f.file_name LIKE CONCAT('%',#{keyword},'%')
AND f.file_type = #{fileType}
ORDER BY f.id DESC LIMIT #{start}, #{length}

SELECT COUNT(*) FROM xxl_kettle_file WHERE group_id = #{groupId}
AND file_name LIKE CONCAT('%',#{keyword},'%')
AND file_type = #{fileType}
